css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #F5F7F3; }
.dcx a[style*="inline-flex"]{ white-space: nowrap; }
.dcx img{ max-width: 100%; }
@media (prefers-reduced-motion: reduce){.dcx *,.dcx *::before,.dcx *::after{ animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; }
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-h1]{ font-size: 32px !important; }
.dcx [data-h2]{ font-size: 24px !important; }
}
@media (max-width: 1180px){.dcx [data-dhero]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-bento]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-bento] > [data-wide]{ grid-column: 1 / -1 !important; }
.dcx [data-day]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; row-gap: 26px; }
.dcx [data-day-line]{ display: none !important; }
.dcx [data-screens]{ grid-template-columns: minmax(0,1fr) !important; }
}
@media (max-width: 720px){.dcx [data-bento],.dcx [data-day]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-win-side]{ display: none !important; }
.dcx [data-win-body]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-kpis]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-phone]{ display: none !important; }
}
